require_once dirname(__DIR__,2).'/src/actions.php';require_method('POST');$u=current_user();$d=request_json();$peer=(string)($d['member_id']??'');if(!valid_uuid($peer)||$peer===$u['id']||!is_bool($d['enabled']??null))json_response(['error'=>['code'=>'invalid_member','message'=>'Invalid member']],400);
mutate($u,$d,'close_friend.set',function($pdo)use($u,$d,$peer){if($d['enabled']){$pair=[$u['id'],$peer];sort($pair);$q=$pdo->prepare('SELECT 1 FROM friendships WHERE user_low=? AND user_high=?');$q->execute($pair);if(!$q->fetchColumn())throw new DomainException('Member must be a friend');$q=$pdo->prepare('INSERT IGNORE INTO close_friends(owner_id,member_id,created_at) VALUES(?,?,UTC_TIMESTAMP(6))');}else{$q=$pdo->prepare('DELETE FROM close_friends WHERE owner_id=? AND member_id=?');}$q->execute([$u['id'],$peer]);return ['ok'=>true];});
